export function getProductBySlug(slug) {
  return PRODUCT_CATALOGUE.find((p) => p.slug === slug || p.id === slug) || null;
}

export function getProductsByCategory(categorySlug) {
  return PRODUCT_CATALOGUE.filter((p) => p.categorySlug === categorySlug);
}

export function getProductsBySubCategory(categorySlug, subCategoryName) {
  return PRODUCT_CATALOGUE.filter(
    (p) =>
      p.categorySlug === categorySlug &&
      p.subCategory.toLowerCase() === decodeURIComponent(subCategoryName).toLowerCase()
  );
}

export function searchProducts(query) {
  if (!query || !query.trim()) return PRODUCT_CATALOGUE;
  const q = query.toLowerCase().trim();
  return PRODUCT_CATALOGUE.filter(
    (p) =>
      p.name.toLowerCase().includes(q) ||
      p.subCategory.toLowerCase().includes(q) ||
      p.category.toLowerCase().includes(q) ||
      p.originDistrict.toLowerCase().includes(q) ||
      p.variety.toLowerCase().includes(q)
  );
}
